<div class="card border-0 shadow-sm mb-4"><div class="card-body"><form method="post" class="row g-3"><div class="col-md-5"><label class="form-label">Nombre del curso</label><input class="form-control" name="nombre" required></div><div class="col-md-4"><label class="form-label">Nivel</label><input class="form-control" name="nivel" required></div><div class="col-md-2"><label class="form-label">Paralelo</label><input class="form-control" name="paralelo" value="A"></div><div class="col-md-1 d-flex align-items-end"><button class="btn btn-primary">Añadir</button></div></form></div></div>
